const base = $('Preparar entrada').first().json;
const catalogo = base.catalogo || { proyectos: [], clientes: [] };
const proyectos = (catalogo.proyectos || []).map(p => `- ${p.nombre} | cliente: ${p.cliente} | estado: ${p.activo ? 'activo' : 'inactivo'} | alias: ${(p.alias || []).join(', ') || '(ninguno)'}`).join('\n');
const clientes = (catalogo.clientes || []).map(c => `- ${c.nombre}`).join('\n');
const paso = String((base.payload || {}).paso || '');
const conBorrador = ['confirmar','corregir','falta_dato','falta_nombre','falta_cliente','falta_proyecto','cliente_ambiguo'].includes(paso);
const borrador = conBorrador
  ? `\nBORRADOR ACTUAL:\n${JSON.stringify(base.payload, null, 2)}\nSi el mensaje corrige o completa el borrador, devuelve solo los campos que cambian; deja los demás en null o [] según corresponda.\n`
  : '';
const prompt = `Eres el módulo de administración de proyectos de Constructora MYRA.
Recibes un mensaje de un administrador o gerente. Tu única tarea es interpretar la intención y extraer los datos. No inventes datos.

ACCIONES VÁLIDAS
- "crear": agregar un proyecto nuevo.
- "editar": cambiar el nombre y/o agregar alias a un proyecto existente.
- "desactivar": marcar un proyecto como inactivo.
- "reactivar": volver a activar un proyecto.
- "listar": mostrar los proyectos.
- "salir": cerrar el modo administración.
- "otro": cualquier mensaje que no corresponda a lo anterior.

REGLAS
1. No inventes datos. Usa null cuando el dato no aparezca.
2. "proyecto": nombre del proyecto mencionado. Para crear, es el nombre nuevo.
3. "proyecto_actual": proyecto que se quiere modificar cuando se cambia el nombre o se agrega un alias.
4. "nuevo_nombre": nombre nuevo en una edición de nombre.
5. "cliente": cliente del proyecto para crear, o cliente para una operación masiva de desactivar/reactivar. "todos": true cuando se piden todos los proyectos.
6. "alias": arreglo de alias mencionados. Para "agrega el alias X", devuelve ["X"].
7. Si el mensaje corrige o completa un BORRADOR ACTUAL, devuelve solo los campos que cambian.
8. La confianza es un número entre 0 y 1 por acción, proyecto y cliente.
9. No escribas explicaciones ni markdown. Devuelve solo JSON.

EJEMPLOS
- "agrega el proyecto Los Robles para el cliente Constructora Andes" -> {"accion":"crear","proyecto":"Los Robles","cliente":"Constructora Andes","alias":[]}
- "cambia el nombre de Peñuelas a Obra Peñuelas Norte" -> {"accion":"editar","proyecto_actual":"Peñuelas","nuevo_nombre":"Obra Peñuelas Norte","alias":[]}
- "agrega el alias el robles al proyecto Los Robles" -> {"accion":"editar","proyecto_actual":"Los Robles","alias":["el robles"]}
- "desactiva la obra La Rinconada" -> {"accion":"desactivar","proyecto_actual":"La Rinconada","alias":[]}
- "reactiva Los Aromos" -> {"accion":"reactivar","proyecto_actual":"Los Aromos","alias":[]}
- "desactiva todos los proyectos del cliente Cliente Demo" -> {"accion":"desactivar","cliente":"Cliente Demo","todos":true,"alias":[]}
- "reactiva todos los proyectos" -> {"accion":"reactivar","todos":true,"alias":[]}
- "lista los proyectos" -> {"accion":"listar","alias":[]}
- "salir" -> {"accion":"salir","alias":[]}

FORMATO EXACTO DE SALIDA
{
  "accion": "crear | editar | desactivar | reactivar | listar | salir | otro",
  "proyecto": "texto o null",
  "proyecto_actual": "texto o null",
  "nuevo_nombre": "texto o null",
  "cliente": "texto o null",
  "todos": false,
  "alias": [],
  "confianza": {"accion": 0.0, "proyecto": 0.0, "cliente": 0.0}
}
${borrador}
PROYECTOS (nombre | cliente | estado | alias):
${proyectos || '- (sin proyectos)'}

CLIENTES:
${clientes || '- (sin clientes)'}

TEXTO DEL USUARIO:
<<<
${base.texto}
>>>

Devuelve solo el JSON.`;
return [{ json: { ...base, prompt } }];

const base = $('Preparar entrada').first().json;
const raw = $input.first().json;
const parsePosible = (value) => {
  if (typeof value !== 'string') return value;
  const limpio = value.replace(/```json/gi, '').replace(/```/g, '').trim();
  try { return JSON.parse(limpio); } catch (error) { return {}; }
};
let parsed = raw && raw.output ? raw.output : raw;
if (parsed && typeof parsed.text === 'string') parsed = parsed.text;
parsed = parsePosible(parsed);
if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) parsed = {};

const prev = base.payload || {};
const paso = String(prev.paso || '');
const continuar = ['confirmar','corregir','falta_dato','falta_nombre','falta_cliente','falta_proyecto','cliente_ambiguo'].includes(paso);
const op = continuar ? { ...prev } : { alias: [] };
const setStr = (key, val) => {
  if (val === undefined || val === null) return;
  const s = String(val).trim();
  if (s) op[key] = s;
};
const acciones = ['crear','editar','desactivar','reactivar','listar','salir','otro'];
if (parsed.accion && acciones.includes(String(parsed.accion).toLowerCase())) op.accion = String(parsed.accion).toLowerCase();
else if (!continuar) op.accion = 'otro';
setStr('proyecto', parsed.proyecto);
setStr('proyecto_actual', parsed.proyecto_actual);
setStr('nuevo_nombre', parsed.nuevo_nombre);
setStr('cliente', parsed.cliente);
if (parsed.todos === true || String(parsed.todos).toLowerCase() === 'true') op.todos = true;
else if (!continuar) op.todos = false;
if (['desactivar', 'reactivar'].includes(op.accion) && (parsed.proyecto_actual || parsed.proyecto) && !parsed.cliente && parsed.todos !== true) {
  delete op.cliente;
  delete op.todos;
  delete op.proyecto_ids;
  delete op.proyecto_nombres;
  delete op.alcance;
}
if (op.accion === 'crear' && parsed.nuevo_nombre && !parsed.proyecto) setStr('proyecto', parsed.nuevo_nombre);
if (Array.isArray(parsed.alias)) {
  const nuevos = parsed.alias.map(a => String(a || '').trim()).filter(Boolean);
  if (nuevos.length) op.alias = [...new Set([...(Array.isArray(op.alias) ? op.alias : []), ...nuevos])];
  else if (!continuar) op.alias = [];
}
if (continuar && op.accion !== prev.accion) {
  delete op.cliente_confirmado;
  delete op.cliente_id;
  delete op.cliente_nombre;
  delete op.proyecto_id;
  delete op.nuevo_nombre;
  delete op.todos;
  delete op.proyecto_ids;
  delete op.proyecto_nombres;
  delete op.alcance;
  if (op.accion !== 'crear') delete op.cliente;
}
if (!op.accion) op.accion = 'otro';
return [{ json: { ...base, operacion: op, original: base, esCorreccion: paso === 'corregir' } }];

const base = $('Preparar entrada').first().json;
const input = $input.first().json || {};
const op = { ...(input.operacion || {}) };
const catalogo = base.catalogo || { proyectos: [], clientes: [] };
const proyectos = Array.isArray(catalogo.proyectos) ? catalogo.proyectos : [];
const clientes = Array.isArray(catalogo.clientes) ? catalogo.clientes : [];
const candidatosProyecto = Array.isArray(input.proyecto_candidatos) ? input.proyecto_candidatos : [];
const candidatosCliente = Array.isArray(input.cliente_candidatos) ? input.cliente_candidatos : [];

const norm = (s) => String(s ?? '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase().replace(/\s+/g, ' ').trim();
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const uniq = (arr) => [...new Set(arr.map(a => String(a || '').trim()).filter(Boolean))];
const findProjectExact = (nombre) => {
  const n = norm(nombre);
  if (!n) return null;
  return proyectos.find(p => norm(p.nombre) === n || (Array.isArray(p.alias) && p.alias.some(a => norm(a) === n))) || null;
};
const findClientExact = (nombre) => {
  const n = norm(nombre);
  if (!n) return null;
  return clientes.find(c => norm(c.nombre) === n) || null;
};
const pickCandidate = (cands, min = 0.55, gap = 0.10) => {
  const lista = (Array.isArray(cands) ? cands : []).filter(c => c && c.nombre).sort((a, b) => Number(b.score) - Number(a.score));
  if (!lista.length) return { match: null, ambiguo: false, lista: [] };
  const best = lista[0];
  const second = lista[1];
  const score = Number(best.score) || 0;
  if (score >= min && (!second || (score - Number(second.score || 0)) >= gap)) return { match: best, ambiguo: false, lista };
  return { match: null, ambiguo: true, lista: lista.slice(0, 3) };
};
const opcionesProyecto = (lista) => lista.map(c => `• ${esc(c.nombre)}${c.cliente ? ` (${esc(c.cliente)})` : ''}`).join('\n');
const respuestaBase = (extra) => ({ ok: false, paso: 'esperando', operacion: op, ...extra });

if (!['crear','editar','desactivar','reactivar','listar','salir','otro'].includes(String(op.accion || ''))) op.accion = 'otro';
if (op.accion === 'listar' || op.accion === 'salir') return [{ json: { ok: true, paso: 'esperando', accion: op.accion, operacion: op, resumen: null } }];
if (op.accion === 'otro') return [{ json: respuestaBase({ pregunta: 'No entendí la operación. Escríbela de otra forma o usa los ejemplos del menú.', error: null }) }];

if (op.accion === 'crear') {
  const nombre = String(op.proyecto || op.nombre || '').trim();
  if (!nombre) return [{ json: respuestaBase({ paso: 'falta_nombre', pregunta: '¿Cómo se llamará el proyecto?', error: null }) }];
  const dup = findProjectExact(nombre);
  if (dup) return [{ json: respuestaBase({ paso: 'falta_nombre', error: `Ya existe el proyecto "${esc(dup.nombre)}".`, pregunta: 'Envíame otro nombre para el proyecto.' }) }];
  const aliasConflicto = proyectos.find(p => Array.isArray(p.alias) && p.alias.some(a => norm(a) === norm(nombre)));
  if (aliasConflicto) return [{ json: respuestaBase({ paso: 'falta_nombre', error: `Ese nombre ya se usa como alias de "${esc(aliasConflicto.nombre)}".`, pregunta: 'Envíame otro nombre para el proyecto.' }) }];

  const clienteTexto = String(op.cliente || op.cliente_nombre || '').trim();
  if (!clienteTexto) return [{ json: respuestaBase({ paso: 'falta_cliente', pregunta: '¿A qué cliente pertenece el proyecto?', error: null }) }];
  const clienteExacto = findClientExact(clienteTexto);
  const clienteId = clienteExacto ? clienteExacto.id : (op.cliente_id ? Number(op.cliente_id) : null);
  const clienteNombre = clienteExacto ? clienteExacto.nombre : (op.cliente_nombre || clienteTexto);
  if (!clienteId && !op.cliente_confirmado) {
    const similares = candidatosCliente
      .filter(c => norm(c.nombre) !== norm(clienteTexto) && Number(c.score) >= 0.45)
      .slice(0, 3);
    if (similares.length) {
      return [{ json: {
        ok: false, paso: 'cliente_ambiguo', error: null,
        operacion: { ...op, proyecto: nombre, nombre, cliente: clienteTexto, cliente_nombre: clienteTexto, cliente_candidatos: similares },
        cliente_candidatos: similares,
        pregunta: `Ya existe un cliente parecido: ${esc(similares[0].nombre)}. ¿Quieres usar ese cliente o crear "${esc(clienteTexto)}"?`
      } }];
    }
  }
  const alias = uniq(Array.isArray(op.alias) ? op.alias : []);
  for (const a of alias) {
    const p = findProjectExact(a);
    if (p) return [{ json: respuestaBase({ paso: 'falta_dato', error: `El alias "${esc(a)}" ya está asociado a "${esc(p.nombre)}".`, pregunta: 'Corrige los alias o envía otro dato.' }) }];
  }
  const resumen = `🏗️ <b>Nuevo proyecto</b>\n\n<b>Nombre:</b> ${esc(nombre)}\n<b>Cliente:</b> ${esc(clienteNombre)}\n<b>Alias:</b> ${alias.length ? alias.map(esc).join(', ') : '(ninguno)'}\n\n¿Confirmas la creación?`;
  return [{ json: {
    ok: true, paso: 'confirmar', accion: 'crear',
    operacion: { ...op, accion: 'crear', proyecto: nombre, nombre, cliente: clienteTexto, cliente_id: clienteId, cliente_nombre: clienteNombre, alias, cliente_confirmado: true },
    resumen, pregunta: null, error: null
  } }];
}

if (op.accion === 'desactivar' || op.accion === 'reactivar') {
  const desactivar = op.accion === 'desactivar';
  const clienteTexto = String(op.cliente || '').trim();
  const esBulk = clienteTexto !== '' || op.todos === true;
  if (esBulk) {
    let clienteId = null;
    let clienteNombre = null;
    let proyectosBulk = [];
    if (clienteTexto) {
      const cliente = findClientExact(clienteTexto);
      if (!cliente) {
        const opciones = (candidatosCliente || [])
          .filter(c => c && c.nombre)
          .sort((a, b) => Number(b.score) - Number(a.score))
          .slice(0, 3);
        return [{ json: respuestaBase({
          paso: 'falta_cliente',
          error: null,
          pregunta: opciones.length
            ? `No encontré ese cliente. ¿A cuál te refieres?\n\n${opciones.map(c => `• ${esc(c.nombre)}`).join('\n')}`
            : 'No encontré ese cliente. Escríbeme el nombre exacto.'
        }) }];
      }
      clienteId = cliente.id;
      clienteNombre = cliente.nombre;
      proyectosBulk = proyectos.filter(p => Number(p.cliente_id) === Number(cliente.id) && Boolean(p.activo) === desactivar);
    } else {
      proyectosBulk = proyectos.filter(p => Boolean(p.activo) === desactivar);
    }
    if (!proyectosBulk.length) {
      const destino = clienteTexto ? `del cliente "${clienteNombre}"` : 'en general';
      return [{ json: respuestaBase({
        paso: 'esperando',
        error: `No hay proyectos ${desactivar ? 'activos' : 'inactivos'} ${destino}.`,
        pregunta: 'Puedes escribir otra operación o salir.'
      }) }];
    }
    const nombres = proyectosBulk.map(p => p.nombre);
    const lista = nombres.slice(0, 30).map(n => `• ${esc(n)}`).join('\n');
    const extra = nombres.length > 30 ? `\n… y ${nombres.length - 30} más` : '';
    const destino = clienteTexto ? clienteNombre : 'Todos los clientes';
    const resumen = `${desactivar ? '⛔' : '✅'} <b>${desactivar ? 'Desactivar' : 'Reactivar'} proyectos</b>\n\n<b>Cliente:</b> ${esc(destino)}\n<b>Proyectos (${nombres.length}):</b>\n${lista}${extra}\n\n¿Confirmas la operación?`;
    return [{ json: {
      ok: true, paso: 'confirmar', accion: op.accion,
      operacion: {
        ...op,
        accion: op.accion,
        alcance: clienteTexto ? 'cliente' : 'todos',
        cliente_id: clienteId,
        cliente_nombre: clienteNombre,
        proyecto_ids: proyectosBulk.map(p => p.id),
        proyecto_nombres: nombres,
        todos: !clienteTexto
      },
      resumen, pregunta: null, error: null
    } }];
  }
}

const proyectoTexto = String(op.proyecto_actual || op.proyecto || op.nombre || '').trim();
let target = findProjectExact(proyectoTexto);
if (!target) {
  const picked = pickCandidate(candidatosProyecto);
  if (picked.match) target = proyectos.find(p => Number(p.id) === Number(picked.match.id)) || null;
  if (!target) {
    const lista = picked.lista.length ? picked.lista : candidatosProyecto.slice(0, 3);
    return [{ json: respuestaBase({
      paso: 'falta_proyecto',
      error: lista.length ? 'No pude identificar el proyecto con certeza.' : 'No encontré ese proyecto.',
      pregunta: lista.length ? `¿A cuál proyecto te refieres?\n\n${opcionesProyecto(lista)}` : 'Escríbeme el nombre exacto del proyecto.'
    }) }];
  }
}

if (op.accion === 'editar') {
  const nuevo = String(op.nuevo_nombre || '').trim() || null;
  const alias = uniq(Array.isArray(op.alias) ? op.alias : []);
  if (!nuevo && !alias.length) return [{ json: respuestaBase({ paso: 'falta_dato', error: null, pregunta: '¿Quieres cambiar el nombre o agregar algún alias?' }) }];
  if (nuevo) {
    const dup = proyectos.find(p => Number(p.id) !== Number(target.id) && norm(p.nombre) === norm(nuevo));
    if (dup) return [{ json: respuestaBase({ paso: 'falta_dato', error: `Ya existe un proyecto con el nombre "${esc(dup.nombre)}".`, pregunta: 'Envíame otro nombre.' }) }];
    const aliasConflicto = proyectos.find(p => Number(p.id) !== Number(target.id) && Array.isArray(p.alias) && p.alias.some(a => norm(a) === norm(nuevo)));
    if (aliasConflicto) return [{ json: respuestaBase({ paso: 'falta_dato', error: `Ese nombre ya se usa como alias de "${esc(aliasConflicto.nombre)}".`, pregunta: 'Envíame otro nombre.' }) }];
  }
  for (const a of alias) {
    const p = proyectos.find(x => Number(x.id) !== Number(target.id) && Array.isArray(x.alias) && x.alias.some(al => norm(al) === norm(a)));
    if (p) return [{ json: respuestaBase({ paso: 'falta_dato', error: `El alias "${esc(a)}" ya está asociado a "${esc(p.nombre)}".`, pregunta: 'Corrige los alias o envía otro dato.' }) }];
    if (proyectos.some(x => Number(x.id) !== Number(target.id) && norm(x.nombre) === norm(a))) {
      return [{ json: respuestaBase({ paso: 'falta_dato', error: `El alias "${esc(a)}" coincide con el nombre de otro proyecto.`, pregunta: 'Envíame otro alias.' }) }];
    }
  }
  const cambios = [];
  if (nuevo) cambios.push(`<b>Nombre:</b> ${esc(target.nombre)} → ${esc(nuevo)}`);
  if (alias.length) cambios.push(`<b>Alias a agregar:</b> ${alias.map(esc).join(', ')}`);
  const resumen = `✏️ <b>Editar proyecto</b>\n\n<b>Proyecto:</b> ${esc(target.nombre)}\n<b>Cliente:</b> ${esc(target.cliente)}\n${cambios.join('\n')}\n\n¿Confirmas el cambio?`;
  return [{ json: {
    ok: true, paso: 'confirmar', accion: 'editar',
    operacion: { ...op, accion: 'editar', proyecto_id: target.id, proyecto_actual: target.nombre, proyecto: target.nombre, nuevo_nombre: nuevo, alias, cliente: target.cliente, cliente_id: target.cliente_id, cliente_nombre: target.cliente },
    resumen, pregunta: null, error: null
  } }];
}

const deseado = op.accion === 'reactivar';
if (Boolean(target.activo) === deseado) {
  return [{ json: respuestaBase({ paso: 'esperando', error: `El proyecto "${esc(target.nombre)}" ya está ${deseado ? 'activo' : 'inactivo'}.`, pregunta: 'Puedes escribir otra operación o salir.' }) }];
}
const resumen = `${deseado ? '✅' : '⛔'} <b>${deseado ? 'Reactivar' : 'Desactivar'} proyecto</b>\n\n<b>Proyecto:</b> ${esc(target.nombre)}\n<b>Cliente:</b> ${esc(target.cliente)}\n\n¿Confirmas la operación?`;
return [{ json: {
  ok: true, paso: 'confirmar', accion: op.accion,
  operacion: { ...op, accion: op.accion, proyecto_id: target.id, proyecto_actual: target.nombre, proyecto: target.nombre, cliente: target.cliente, cliente_id: target.cliente_id, cliente_nombre: target.cliente },
  resumen, pregunta: null, error: null
} }];

const base = $('Preparar entrada').first().json;
const p = base.payload || {};
const op = { ...p, alias: Array.isArray(p.alias) ? p.alias : [] };
let texto = String(base.texto || '').trim();
const paso = String(p.paso || '');
const limpiar = (s, patron) => s.replace(patron, '').trim();
if (paso === 'falta_nombre') {
  texto = limpiar(texto, /^(el nombre (es|será|sera)|ponle|se llamará|se llamara|nombre:)\s*/i);
  op.proyecto = texto;
} else if (paso === 'falta_cliente') {
  texto = limpiar(texto, /^(el cliente (es|será|sera)|cliente:)\s*/i);
  op.cliente = texto;
} else if (paso === 'falta_proyecto') {
  texto = limpiar(texto, /^(el proyecto (es|será|sera)|proyecto:)\s*/i);
  op.proyecto_actual = texto;
  op.proyecto = texto;
} else if (paso === 'cliente_ambiguo') {
  texto = limpiar(texto, /^(usa|usar|crea|crear|el cliente es)\s*/i);
  op.cliente = texto;
}
if (op.accion === 'crear') op.nombre = op.proyecto || '';
return [{ json: { ...base, operacion: op, original: base, esCorreccion: false } }];

const base = $('Preparar entrada').first().json;
const p = base.payload || {};
const cands = Array.isArray(p.cliente_candidatos) ? p.cliente_candidatos : [];
const cand = cands[0] || null;
const op = {
  ...p,
  cliente_id: cand ? cand.id : null,
  cliente_nombre: cand ? cand.nombre : (p.cliente || p.cliente_nombre),
  cliente: cand ? cand.nombre : (p.cliente || p.cliente_nombre),
  cliente_confirmado: true,
  cliente_candidatos: []
};
return [{ json: { ...base, operacion: op, proyecto_candidatos: [], cliente_candidatos: [], original: base } }];

const base = $('Preparar entrada').first().json;
const p = base.payload || {};
const op = {
  ...p,
  cliente_id: null,
  cliente_nombre: p.cliente || p.cliente_nombre,
  cliente: p.cliente || p.cliente_nombre,
  cliente_confirmado: true,
  cliente_candidatos: []
};
return [{ json: { ...base, operacion: op, proyecto_candidatos: [], cliente_candidatos: [], original: base } }];

const base = $('Preparar entrada').first().json;
const proyectos = (base.catalogo && base.catalogo.proyectos) ? base.catalogo.proyectos : [];
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const lineas = proyectos.map(p => {
  const estado = p.activo ? '✅' : '⛔';
  const alias = (p.alias || []).length ? `\n   <i>Alias: ${p.alias.map(esc).join(', ')}</i>` : '';
  return `${estado} <b>${esc(p.nombre)}</b> — ${esc(p.cliente)}${alias}`;
});
const maxCharsLista = 3200;
let usadosLista = 0;
const lineasVisibles = [];
for (const linea of lineas) {
  if (usadosLista + linea.length + 1 > maxCharsLista) break;
  lineasVisibles.push(linea);
  usadosLista += linea.length + 1;
}
const notaLista = lineasVisibles.length < lineas.length
  ? `\n\n… y ${lineas.length - lineasVisibles.length} proyecto(s) más.`
  : '';
const respuesta = `📁 <b>Proyectos (${proyectos.length})</b>\n\n${lineasVisibles.length ? lineasVisibles.join('\n') + notaLista : '• (no hay proyectos)'}`;
return [{ json: { respuesta, telegram_chat_id: base.telegram_chat_id } }];

const base = $('Cuando se ejecuta').first().json;
let payload = base.payload || {};
if (typeof payload === 'string') {
  try { payload = JSON.parse(payload); } catch (error) { payload = {}; }
}
let catalogo = base.catalogo || { proyectos: [], clientes: [] };
if (typeof catalogo === 'string') {
  try { catalogo = JSON.parse(catalogo); } catch (error) { catalogo = { proyectos: [], clientes: [] }; }
}
return [{ json: {
  ...base,
  catalogo,
  payload,
  texto: base.texto || '',
  callback_data: base.callback_data || '',
  accion: base.accion || 'interpretar',
  paso: payload.paso || base.paso || ''
} }];
